import { useId } from 'react'
import { ANTENNA, BODY, MONO_N, SCREEN, WORD_MEDIA, WORD_NEW, WORD_W } from '@/lib/logo-data'
import { cn } from '@/lib/utils'

/*
 * New Media identity: a retro TV with a serif italic "n" on screen, and the
 * wordmark "new" (serif italic, gradient) + "media" (sans). All outlined paths,
 * generated by qa/make-logo.mjs, so it renders the same without fonts.
 */

function Defs({ id }: { id: string }) {
  return (
    <defs>
      <linearGradient id={`${id}g`} x1="0" y1="0" x2="1" y2="1">
        <stop offset="0" stopColor="#2f8cff" />
        <stop offset=".45" stopColor="#2f54eb" />
        <stop offset="1" stopColor="#8a3cf0" />
      </linearGradient>
      <radialGradient id={`${id}l`} cx=".3" cy=".2" r=".9">
        <stop offset="0" stopColor="#fff" stopOpacity=".28" />
        <stop offset=".6" stopColor="#fff" stopOpacity="0" />
      </radialGradient>
    </defs>
  )
}

function Mark({ id }: { id: string }) {
  const g = `url(#${id}g)`
  return (
    <>
      <path d={ANTENNA} stroke={g} strokeWidth="6" strokeLinecap="round" fill="none" />
      <circle cx="43" cy="10" r="4.5" fill={g} />
      <circle cx="77" cy="10" r="4.5" fill={g} />
      <path d={BODY} fill={g} />
      <path d={BODY} fill={`url(#${id}l)`} />
      <path d={SCREEN} fill="#fff" />
      <path d={MONO_N} fill={g} />
      <circle cx="99.5" cy="58" r="5" fill="#fff" />
      <circle cx="99.5" cy="74" r="3.6" fill="#fff" opacity=".85" />
      <path d="M95 86h9M95 91h9M95 96h9" stroke="#fff" strokeWidth="2.2" strokeLinecap="round" opacity=".7" />
    </>
  )
}

/** Horizontal lockup for the nav. "media" takes the current text colour. */
export function Logo({ className, title = 'New Media' }: { className?: string; title?: string }) {
  const id = useId().replace(/:/g, '')
  const W = 120 + 26 + WORD_W
  return (
    <svg viewBox={`0 0 ${W} 120`} className={cn('block h-8 w-auto sm:h-9', className)} role="img" aria-label={title}>
      <Defs id={id} />
      <Mark id={id} />
      <g transform="translate(146 4)">
        <path d={WORD_NEW} fill={`url(#${id}g)`} />
        <path d={WORD_MEDIA} fill="currentColor" />
      </g>
    </svg>
  )
}

/** Stacked lockup: mark above the wordmark. */
export function LogoFull({ className, title = 'New Media' }: { className?: string; title?: string }) {
  const id = useId().replace(/:/g, '')
  return (
    <svg viewBox={`0 0 ${WORD_W} 270`} className={cn('block', className)} role="img" aria-label={title}>
      <Defs id={id} />
      <g transform={`translate(${(WORD_W - 120) / 2} 0)`}>
        <Mark id={id} />
      </g>
      <g transform="translate(0 150)">
        <path d={WORD_NEW} fill={`url(#${id}g)`} />
        <path d={WORD_MEDIA} fill="currentColor" />
      </g>
    </svg>
  )
}

/** The TV mark on its own. */
export function LogoMark({ className }: { className?: string }) {
  const id = useId().replace(/:/g, '')
  return (
    <svg viewBox="0 0 120 120" className={cn('block', className)} aria-hidden>
      <Defs id={id} />
      <Mark id={id} />
    </svg>
  )
}
